std::vector<int> data(100);

// Initialize entire container range (0 to 99) to 99
std::fill(data.begin(), data.end(), 99);

// Initialize a C-style array range
int arr[5] = {0};
std::fill(arr, arr + 5, 42);

// Fill the first N elements (start iterator, count, value)
// Sets first 10 elements of data to 5
std::fill_n(data.begin(), 10, 5);

// Fill a sub-range using iterator arithmetic (elements 50 to 74)
auto sub_start = data.begin() + 50;
auto sub_end = sub_start + 25;
std::fill(sub_start, sub_end, 10);
